@startuml

class User {
  + name
  + surname
}

class Subscriber extends User {
  + phone
  + address
}

class Card {
  + credit
  + code
}

class MovieShop {
  + listMovies()
  + order()
  + subscribe()
}

class Movie {
  + name
  + type : MovieType
}

class MovieRent {
  + status : MovieRentStatus
  + loanDate
  + price
}

class MovieBuy {
  + status : MovieBuyStatus
  + sellingPrice
}

class Order {
  + date
}

enum MovieType {
  DVD
  VHS
}

enum MovieRentStatus {
  in
  out
}

enum MovieBuyStatus {
  present
  to order
}

User "*" --> "1" MovieShop : uses
MovieShop "1" -- "*" Card : make
MovieShop "1" --> "*" Order : make
MovieShop "1" --> "*" Movie : contains
Subscriber "1" --> "1" Card : has
Subscriber "*" --> "1..*" MovieRent : hire
User "*" --> "1..*" MovieBuy : buy
Order "*" -- "1..*" MovieBuy : related to
Order "*" -- "1..*" MovieRent : related to

@enduml

